888	fn rel_time(iso: &str) -> String {
889	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return iso.to_string(); };
890	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
891	    if secs < 604_800 {
892	        match secs {
893	            s if s < 60     => "just now".into(),
894	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
895	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
896	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
897	        }
898	    } else {
899	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
900	    }
901	}
